func TextCheckStyle(style int32) int32 {
	if (style&SINGLE) != 0 && (style&MULTI) != 0 {
		style &= ^MULTI
	}
	style = WidgetCheckBits(style, LEFT, CENTER, RIGHT, 0, 0, 0)
	if (style & SEARCH) != 0 {
		style |= SINGLE | BORDER
		style &= ^(PASSWORD | WRAP)
	} else {
		if (style & SINGLE) != 0 {
			style &= ^(H_SCROLL | V_SCROLL | WRAP)
		}
	}
	if (style & WRAP) != 0 {
		style |= MULTI
		style &= ^H_SCROLL
	}
	if (style & MULTI) != 0 {
		style &= ^PASSWORD
	}
	if (style & (SINGLE | MULTI)) != 0 {
		return style
	}
	if (style & (H_SCROLL | V_SCROLL)) != 0 {
		return style | MULTI
	}
	return style | SINGLE
}

func upcastTextToControl(x *Text) *Control {
	if x == nil {
		return nil
	}
	return &x.Control
}

